class AdminApp extends StatelessWidget { const AdminApp({super.key}); @override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Message Admin',theme:ThemeData(colorSchemeSeed:const Color(0xff246bfd),useMaterial3:true),home:const Gate()); }
class Gate extends StatelessWidget { const Gate({super.key}); @override Widget build(BuildContext c)=>StreamBuilder<User?>(stream:FirebaseAuth.instance.authStateChanges(),builder:(c,s)=>s.connectionState==ConnectionState.waiting?const Scaffold(body:Center(child:CircularProgressIndicator())):s.data==null?const LoginPage():const HomePage()); }
class LoginPage extends StatefulWidget { const LoginPage({super.key}); @override State<LoginPage> createState()=>_LoginPageState(); }
class _LoginPageState extends State<LoginPage> { final email=TextEditingController(),pass=TextEditingController(); bool busy=false; String? error;
Future<void> login() async { setState(() { busy = true; error = null; }); try { await FirebaseAuth.instance.signInWithEmailAndPassword(email:email.text.trim(),password:pass.text); } on FirebaseAuthException catch(e){setState(()=>error=e.message??e.code);} finally {if(mounted)setState(()=>busy=false);} }
@override void dispose(){email.dispose();pass.dispose();super.dispose();}
@override Widget build(BuildContext c)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:420),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[const Icon(Icons.admin_panel_settings,size:76,color:Color(0xff246bfd)),Text('Admin Login',style:Theme.of(c).textTheme.headlineMedium),const SizedBox(height:24),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:pass,obscureText:true,decoration:const InputDecoration(labelText:'Password',border:OutlineInputBorder())),if(error!=null)Text(error!,style:const TextStyle(color:Colors.red)),const SizedBox(height:18),SizedBox(width:double.infinity,child:FilledButton(onPressed:busy?null:login,child:busy?const CircularProgressIndicator():const Text('Login'))),const Text('اډمین حساب د Firebase Authentication په برخه کې جوړ کړئ.')])))));
