class HomePage extends StatelessWidget { const HomePage({super.key}); @override Widget build(BuildContext c){final ref=FirebaseDatabase.instance.ref('messages'); return Scaffold(appBar:AppBar(title:const Text('Message Admin'),actions:[IconButton(onPressed:()=>FirebaseAuth.instance.signOut(),icon:const Icon(Icons.logout))]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>edit(c,ref),icon:const Icon(Icons.add),label:const Text('نوی پیغام')),body:StreamBuilder<DatabaseEvent>(stream:ref.onValue,builder:(c,s){if(s.hasError)return Center(child:Text('Database error: \${s.error}'));if(!s.hasData)return const Center(child:CircularProgressIndicator());final raw=s.data!.snapshot.value;if(raw==null)return const Center(child:Text('تر اوسه پیغام نشته.'));final list=(raw as Map).entries.map((e){final v=Map<dynamic,dynamic>.from(e.value as Map);return {'id':e.key.toString(),'text':(v['text']??'').toString()};}).toList().reversed.toList();return ListView.builder(padding:const EdgeInsets.all(12),itemCount:list.length,itemBuilder:(c,i)=>Card(child:ListTile(title:Text(list[i]['text']!),trailing:PopupMenuButton<String>(onSelected:(v)=>v=='edit'?edit(c,ref,id:list[i]['id'],old:list[i]['text']):remove(c,ref,list[i]['id']!),itemBuilder:(_)=>const [PopupMenuItem(value:'edit',child:Text('سمول')),PopupMenuItem(value:'delete',child:Text('حذف'))]))));}));}}
Future<void> edit(BuildContext c,DatabaseReference ref,{String? id,String? old}) async {final t=TextEditingController(text:old??'');final value=await showDialog<String>(context:c,builder:(d)=>AlertDialog(title:Text(id==null?'نوی پیغام':'پیغام سمول'),content:TextField(controller:t,maxLines:5,decoration:const InputDecoration(hintText:'پیغام ولیکئ',border:OutlineInputBorder())),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('لغوه')),FilledButton(onPressed:()=>Navigator.pop(d,t.text.trim()),child:const Text('Save'))]));final msg=value?.trim()??'';t.dispose();if(msg.isEmpty)return;try{if(id==null){await ref.push().set({'text':msg,'createdAt':ServerValue.timestamp});}else{await ref.child(id).update({'text':msg,'updatedAt':ServerValue.timestamp});}if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('پیغام ثبت شو.')));}catch(e){if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('خطا: $e')));}}
Future<void> remove(BuildContext c,DatabaseReference ref,String id) async {final yes=await showDialog<bool>(context:c,builder:(d)=>AlertDialog(title:const Text('حذف؟'),content:const Text('پیغام حذف شي؟'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('نه')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('حذف'))]));if(yes==true)await ref.child(id).remove();}
